# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

See [`example-retry-policy.md`](example-retry-policy.md) for a test-first sample.

//! Integration tests for the public crate surface.
//!
//! These link against the crate as a downstream consumer would: they can only
//! use what `src/lib.rs` re-exports. Treat them as the regression suite for the
//! crate's public contract — if a change breaks a test here, it is a breaking
//! change for users.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use tinyruntime_nodejs::{
    CONTRACT_VERSION, DEFAULT_VERSION, Error, Language, NODEJS, distribution, harness, layout,
    major, names, satisfies,
};

#[test]
fn the_provider_serves_the_shared_interface_from_the_contract() {
    assert_eq!(
        names::PROVIDER_INTERFACE,
        tinyruntime_nodejs::PROVIDER_INTERFACE
    );
    assert_eq!(
        names::providers::NODEJS_OBJECT_PATH,
        names::object_path_for(names::providers::NODEJS)
    );
    assert_eq!(names::PROVIDER_METHODS.len(), 5);
    assert_eq!(Language::nodejs().as_str(), NODEJS);
}

#[test]
fn the_contract_is_re_exported_so_consumers_take_one_dependency() {
    let same: tinyruntime_bus::WorkerHarness = harness();
    assert_eq!(same, harness());
    assert!(tinyruntime_nodejs::is_compatible_with_contract());
    let _ = CONTRACT_VERSION;
}

#[test]
fn the_default_version_is_one_this_crate_can_reason_about() {
    assert!(major(DEFAULT_VERSION).is_some());
    assert!(satisfies(DEFAULT_VERSION, DEFAULT_VERSION));
}

#[test]
fn the_host_table_and_the_layout_agree_about_this_platform() {
    // A host the archive table covers must also be one the layout knows the
    // shape of, or an install would succeed and then be unusable.
    if distribution::host_archive().is_ok() {
        let bin = layout::bin_dir(std::path::Path::new("/cache/node-v22.11.0"));
        assert!(bin.starts_with("/cache/node-v22.11.0"));
        assert!(!layout::executable_name("node").is_empty());
    }
}

#[test]
fn an_unsupported_host_is_reported_by_name() {
    let error = distribution::archive_for("plan9", "x86_64").expect_err("no build exists");
    assert!(matches!(error, Error::UnsupportedHost { .. }));
}

//! End-to-end tests for the shipped worker harness, against a real `node`.
//!
//! The harness is the one part of this crate that is not Rust, so nothing else
//! in the suite can check that it actually speaks the protocol. These tests
//! stand in for the router: they listen on loopback, launch the harness the way
//! the router would, complete the handshake, and run jobs through it.
//!
//! They skip when the machine has no `node`, so the suite stays hermetic on a
//! runner without one rather than failing for the wrong reason.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::PathBuf;
use std::process::Stdio;
use std::time::Duration;

use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader, Lines};
use tokio::net::{TcpListener, TcpStream};
use tokio::process::{Child, Command};

use tinyruntime_nodejs::{WORKER_PROTOCOL_VERSION, harness};

/// How long any single step may take before the test gives up.
const STEP_TIMEOUT: Duration = Duration::from_secs(30);

/// Read and discard a child stream, so the job writing to it never blocks.
fn drain(stream: impl tokio::io::AsyncRead + Send + Unpin + 'static) {
    tokio::spawn(async move {
        let mut lines = BufReader::new(stream).lines();
        while let Ok(Some(_)) = lines.next_line().await {}
    });
}

/// A harness process under test, plus the protocol connection to it.
struct Harness {
    _child: Child,
    writer: tokio::io::WriteHalf<TcpStream>,
    lines: Lines<BufReader<tokio::io::ReadHalf<TcpStream>>>,
    _scratch: tempfile::TempDir,
    cwd: PathBuf,
}

impl Harness {
    /// Launch the harness the way the router would, or `None` without `node`.
    async fn launch() -> Option<Self> {
        let usable = Command::new("node")
            .arg("--version")
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status()
            .await
            .is_ok_and(|status| status.success());
        if !usable {
            eprintln!("skipped: this machine has no usable `node`");
            return None;
        }

        let scratch = tempfile::tempdir().unwrap();
        let harness = harness();
        let script = scratch.path().join(&harness.filename);
        std::fs::write(&script, &harness.source).unwrap();

        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let token = "test-secret-token";

        let mut child = Command::new("node")
            .args(harness.command_args(&script.to_string_lossy()))
            .env("TINYRUNTIME_PROTOCOL_ADDR", address.to_string())
            .env("TINYRUNTIME_PROTOCOL_TOKEN", token)
            .env("PATH", std::env::var("PATH").unwrap_or_default())
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .kill_on_drop(true)
            .spawn()
            .unwrap();

        let (stream, _) = tokio::time::timeout(STEP_TIMEOUT, listener.accept())
            .await
            .expect("the harness connected back")
            .unwrap();
        let (reader, writer) = tokio::io::split(stream);
        let mut lines = BufReader::new(reader).lines();

        let handshake: serde_json::Value = serde_json::from_str(
            &tokio::time::timeout(STEP_TIMEOUT, lines.next_line())
                .await
                .expect("the handshake arrived")
                .unwrap()
                .expect("the harness sent a handshake"),
        )
        .unwrap();

        assert_eq!(handshake["ready"], serde_json::json!(true));
        assert_eq!(
            handshake["protocol"],
            serde_json::json!(WORKER_PROTOCOL_VERSION)
        );
        assert_eq!(handshake["language"], serde_json::json!("nodejs"));
        assert_eq!(
            handshake["token"],
            serde_json::json!(token),
            "the harness must echo the secret it was given"
        );

        // Drain the child's own file descriptors, exactly as the router does.
        // This is not tidiness: a job that writes to fd 1 gets EPIPE if nothing
        // is reading, and blocks outright once the pipe fills.
        if let Some(stdout) = child.stdout.take() {
            drain(stdout);
        }
        if let Some(stderr) = child.stderr.take() {
            drain(stderr);
        }
        let cwd = scratch.path().to_path_buf();
        Some(Self {
            _child: child,
            writer,
            lines,
            _scratch: scratch,
            cwd,
        })
    }

    /// Run one job and return its reply.
    async fn run(&mut self, id: &str, code: &str, timeout_ms: Option<u64>) -> serde_json::Value {
        let mut request = serde_json::json!({
            "id": id,
            "code": code,
            "cwd": self.cwd.to_string_lossy(),
        });
        if let Some(timeout_ms) = timeout_ms {
            request["timeout_ms"] = serde_json::json!(timeout_ms);
        }

        let mut line = serde_json::to_string(&request).unwrap();
        line.push('\n');
        self.writer.write_all(line.as_bytes()).await.unwrap();
        self.writer.flush().await.unwrap();

        let reply = tokio::time::timeout(STEP_TIMEOUT, self.lines.next_line())
            .await
            .expect("the harness replied")
            .unwrap()
            .expect("the harness sent a reply");
        let reply: serde_json::Value = serde_json::from_str(&reply).unwrap();
        assert_eq!(
            reply["id"],
            serde_json::json!(id),
            "reply was for another job"
        );
        reply
    }
}

#[tokio::test]
async fn the_harness_runs_a_job_and_reports_its_output() {
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let reply = harness.run("1", "console.log(6 * 7)", None).await;
    assert_eq!(reply["ok"], serde_json::json!(true));
    assert_eq!(reply["stdout"], serde_json::json!("42\n"));
    assert_eq!(reply["exit_code"], serde_json::json!(0));
}

#[tokio::test]
async fn one_warm_worker_serves_many_jobs() {
    // The entire reason the pool exists. If the harness exited after a job, this
    // would fail on the second one.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    for index in 0..3 {
        let reply = harness
            .run(
                &index.to_string(),
                &format!("console.log({index} + 1)"),
                None,
            )
            .await;
        assert_eq!(
            reply["stdout"],
            serde_json::json!(format!("{}\n", index + 1))
        );
    }
}

#[tokio::test]
async fn a_job_that_throws_reports_a_non_zero_exit_without_killing_the_worker() {
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let thrown = harness.run("1", "throw new Error('boom')", None).await;
    assert_eq!(
        thrown["ok"],
        serde_json::json!(true),
        "the harness ran it; the job failed"
    );
    assert_ne!(thrown["exit_code"], serde_json::json!(0));
    assert!(thrown["stderr"].as_str().unwrap().contains("boom"));

    // The worker must survive a thrown job, or one bad job would cost a respawn.
    let after = harness.run("2", "console.log('still here')", None).await;
    assert_eq!(after["stdout"], serde_json::json!("still here\n"));
}

#[tokio::test]
async fn a_job_that_exits_the_process_does_not_take_the_worker_down() {
    // Each job runs in its own worker_thread precisely so `process.exit()` kills
    // the thread rather than the long-lived host process.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let exited = harness.run("1", "process.exit(3)", None).await;
    assert_eq!(exited["exit_code"], serde_json::json!(3));

    let after = harness.run("2", "console.log('survived')", None).await;
    assert_eq!(after["stdout"], serde_json::json!("survived\n"));
}

#[tokio::test]
async fn relative_paths_resolve_against_the_job_directory() {
    // A shared warm worker runs wherever the last job left it unless the harness
    // enters each job's directory. Getting this wrong escapes the caller's sandbox.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    std::fs::write(harness.cwd.join("probe.txt"), b"RELATIVE_OK").unwrap();

    let reply = harness
        .run(
            "1",
            "process.stdout.write(require('fs').readFileSync('./probe.txt', 'utf8'))",
            None,
        )
        .await;
    assert_eq!(reply["stdout"], serde_json::json!("RELATIVE_OK"));
}

#[tokio::test]
async fn a_job_whose_directory_is_missing_fails_rather_than_running_elsewhere() {
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let sentinel = harness.cwd.join("must-not-exist.txt");
    harness.cwd = harness.cwd.join("deleted-sandbox");

    let reply = harness
        .run(
            "1",
            "require('fs').writeFileSync('must-not-exist.txt', 'escaped')",
            None,
        )
        .await;
    assert_eq!(reply["ok"], serde_json::json!(false), "the job ran anyway");
    assert!(
        reply["error"]
            .as_str()
            .unwrap()
            .contains("failed to set worker cwd")
    );
    assert!(!sentinel.exists(), "the job escaped its sandbox");
}

#[tokio::test]
async fn a_job_that_never_finishes_is_aborted_at_its_deadline() {
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    // A bare unresolved promise would not do: with nothing else pending, the
    // worker's event loop drains and the thread exits on its own, exactly as
    // `node -e` does. A live timer is what actually keeps a job running.
    let reply = harness
        .run(
            "1",
            "await new Promise((resolve) => setTimeout(resolve, 60000))",
            Some(1_000),
        )
        .await;
    assert_eq!(reply["timed_out"], serde_json::json!(true));

    // And the worker is still usable afterwards.
    let after = harness.run("2", "console.log('alive')", None).await;
    assert_eq!(after["stdout"], serde_json::json!("alive\n"));
}

#[tokio::test]
async fn a_job_cannot_forge_a_reply_over_its_own_stdout() {
    // The reason the protocol has its own socket: a job writing a frame-shaped
    // line to fd 1 must not be able to answer its own request.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let reply = harness
        .run(
            "1",
            r"require('fs').writeSync(1, JSON.stringify({ id: '1', ok: true, stdout: 'FORGED' }) + '\n');
console.log('REAL')",
            None,
        )
        .await;

    // The forged frame went to the process's real file descriptor, which the
    // router drains and logs and never parses. What matters is that it did not
    // become this job's reply: the reply is the harness's own, and the job's
    // captured output is only what it wrote through the worker's own stream.
    assert_eq!(reply["ok"], serde_json::json!(true), "reply was {reply}");
    assert_eq!(
        reply["stdout"],
        serde_json::json!("REAL\n"),
        "a job's fd-level write reached the protocol reply: {reply}"
    );
    assert_eq!(reply["exit_code"], serde_json::json!(0));
}

#[tokio::test]
async fn top_level_await_and_dynamic_import_work_like_node_dash_e() {
    // Both depend on the flags the harness ships with; without them this fails
    // at runtime rather than at launch.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let reply = harness
        .run(
            "1",
            "const fs = await import('fs'); console.log(typeof fs.readFileSync)",
            None,
        )
        .await;
    assert_eq!(reply["stdout"], serde_json::json!("function\n"));
}

#[tokio::test]
async fn a_job_reads_end_of_file_on_standard_input() {
    // Standard input must never be the protocol stream, or a job that read it
    // would consume the next request.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let reply = harness
        .run(
            "1",
            "console.log(JSON.stringify(require('fs').readFileSync(0, 'utf8')))",
            Some(5_000),
        )
        .await;
    assert_eq!(reply["stdout"], serde_json::json!("\"\"\n"));
}

//! Unit tests for the crate-wide error type.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::Error;

#[test]
fn messages_are_lowercase_and_unpunctuated() {
    let errors = [
        Error::UnsupportedHost {
            os: "freebsd".to_string(),
            arch: "x86_64".to_string(),
        },
        Error::InvalidVersion("latest".to_string()),
        Error::DigestUnavailable {
            version: "v22.11.0".to_string(),
            reason: "the request timed out".to_string(),
        },
    ];
    for error in errors {
        let rendered = error.to_string();
        assert!(
            !rendered.ends_with('.'),
            "`{rendered}` ends with punctuation"
        );
        let first = rendered.chars().next().expect("a non-empty message");
        assert!(!first.is_uppercase(), "`{rendered}` starts with a capital");
    }
}

#[test]
fn an_unsupported_host_names_the_machine_it_refused() {
    let rendered = Error::UnsupportedHost {
        os: "freebsd".to_string(),
        arch: "riscv64".to_string(),
    }
    .to_string();
    assert!(rendered.contains("freebsd/riscv64"), "got `{rendered}`");
}

#[test]
fn an_invalid_version_quotes_what_was_asked_for() {
    let rendered = Error::InvalidVersion("latest".to_string()).to_string();
    assert!(rendered.contains("`latest`"), "got `{rendered}`");
}

//! Unit tests for the Node.js install layout.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::fs;
use std::path::Path;

use super::{bin_dir, executable_name, from_bin_dir};

/// Build the platform's bin directory with the named tools in it.
fn fabricate(root: &Path, tools: &[&str]) -> std::path::PathBuf {
    let bin = bin_dir(root);
    fs::create_dir_all(&bin).unwrap();
    for tool in tools {
        fs::write(bin.join(executable_name(tool)), b"").unwrap();
    }
    bin
}

#[cfg(unix)]
#[test]
fn unix_keeps_its_tools_under_bin() {
    let root = Path::new("/cache/node-v22.11.0");
    assert_eq!(bin_dir(root), root.join("bin"));
    assert_eq!(executable_name("node"), "node");
    assert_eq!(executable_name("npm"), "npm");
}

#[cfg(windows)]
#[test]
fn windows_keeps_its_tools_at_the_install_root() {
    // The official Windows zip ships no `bin/` directory at all.
    let root = Path::new("C:/cache/node-v22.11.0");
    assert_eq!(bin_dir(root), root);
    assert_eq!(executable_name("node"), "node.exe");
    assert_eq!(
        executable_name("npm"),
        "npm.cmd",
        "npm must be reached through its launcher, not its script"
    );
}

#[test]
fn a_layout_records_every_tool_that_is_present() {
    let scratch = tempfile::tempdir().unwrap();
    let bin = fabricate(scratch.path(), &["node", "npm", "npx"]);

    let layout = from_bin_dir(&bin, "22.11.0");
    assert_eq!(layout.version, "22.11.0");
    for tool in super::TOOLS {
        assert!(layout.executable(tool).is_some(), "{tool} was not recorded");
    }
}

#[test]
fn a_tool_that_is_absent_is_not_claimed() {
    // Claiming a path that is not there turns a clear "this install has no npm"
    // into a confusing spawn failure much later.
    let scratch = tempfile::tempdir().unwrap();
    let bin = fabricate(scratch.path(), &["node"]);

    let layout = from_bin_dir(&bin, "22.11.0");
    assert!(layout.executable("node").is_some());
    assert!(layout.executable("npm").is_none());
}

#[tokio::test]
async fn a_directory_with_no_node_is_not_a_toolchain() {
    let scratch = tempfile::tempdir().unwrap();
    fs::create_dir_all(bin_dir(scratch.path())).unwrap();
    assert!(super::describe(scratch.path(), "v22.11.0").await.is_none());
}

#[tokio::test]
async fn an_empty_directory_is_not_a_toolchain() {
    let scratch = tempfile::tempdir().unwrap();
    assert!(super::describe(scratch.path(), "v22.11.0").await.is_none());
}

/// Write an executable standing in for `node`, printing `version`.
///
/// Waits until the script actually runs before returning. A file written and
/// immediately executed can transiently fail — the kernel may still see a writer
/// on it — and `probe_version` reports any failure as "no interpreter", which
/// would surface here as a confusing assertion failure rather than as the flake
/// it is.
#[cfg(unix)]
fn fake_node(bin: &Path, version: &str) {
    use std::os::unix::fs::PermissionsExt;

    let path = bin.join(super::executable_name("node"));
    fs::write(&path, format!("#!/bin/sh\necho '{version}'\n")).expect("the script writes");
    fs::set_permissions(&path, fs::Permissions::from_mode(0o755))
        .expect("the script is executable");

    for _ in 0..50 {
        if std::process::Command::new(&path)
            .arg("--version")
            .output()
            .is_ok_and(|out| out.status.success())
        {
            return;
        }
        std::thread::sleep(std::time::Duration::from_millis(20));
    }
    panic!(
        "the fake interpreter at {} never became runnable",
        path.display()
    );
}

#[cfg(unix)]
#[tokio::test]
async fn an_install_on_the_requested_major_line_is_described() {
    let scratch = tempfile::tempdir().unwrap();
    let bin = fabricate(scratch.path(), &["npm", "npx"]);
    fake_node(&bin, "v22.9.0");

    let layout = super::describe(scratch.path(), "v22.11.0")
        .await
        .expect("a compatible install is described");

    assert_eq!(layout.version, "22.9.0");
    assert_eq!(layout.bin_dir, bin.to_string_lossy());
    for tool in super::TOOLS {
        assert!(layout.executable(tool).is_some(), "{tool} was not recorded");
    }
}

#[cfg(unix)]
#[tokio::test]
async fn an_install_on_another_major_line_is_not_described() {
    // The router scans a cache that may hold several versions. Reporting the
    // wrong one would install nothing and run the wrong interpreter.
    let scratch = tempfile::tempdir().unwrap();
    let bin = fabricate(scratch.path(), &[]);
    fake_node(&bin, "v20.11.0");

    assert!(super::describe(scratch.path(), "v22.11.0").await.is_none());
}

#[cfg(unix)]
#[tokio::test]
async fn an_install_whose_interpreter_does_not_answer_is_not_described() {
    use std::os::unix::fs::PermissionsExt;

    let scratch = tempfile::tempdir().unwrap();
    let bin = fabricate(scratch.path(), &[]);
    let path = bin.join(super::executable_name("node"));
    fs::write(&path, "#!/bin/sh\nexit 1\n").unwrap();
    fs::set_permissions(&path, fs::Permissions::from_mode(0o755)).unwrap();

    assert!(super::describe(scratch.path(), "v22.11.0").await.is_none());
}

#[test]
fn the_windows_layout_is_checked_everywhere_rather_than_only_on_windows() {
    // The official Windows zip has no `bin/` directory, and `npm` is a batch
    // shim rather than the executable. Both are only correct by matching what
    // the release ships, and neither is exercised by a `cfg!` branch on Linux.
    let root = Path::new("/cache/node-v22.11.0");
    assert_eq!(super::bin_dir_for(root, true), root);
    assert_eq!(super::bin_dir_for(root, false), root.join("bin"));

    assert_eq!(super::executable_name_for("node", true), "node.exe");
    assert_eq!(super::executable_name_for("npm", true), "npm.cmd");
    assert_eq!(super::executable_name_for("npx", true), "npx.cmd");
    assert_eq!(super::executable_name_for("npm", false), "npm");
}

//! Unit tests for host interpreter detection.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::Path;

use tinyruntime_bus::RuntimeSettings;

use super::{candidates, detect, detect_in, locate, probe_version};

#[test]
fn a_preferred_command_is_tried_before_the_default() {
    let ordered = candidates(Some("/opt/node/bin/node"));
    assert_eq!(ordered[0], "/opt/node/bin/node");
    assert_eq!(ordered[1], "node");
}

#[test]
fn the_default_candidate_is_not_repeated() {
    assert_eq!(candidates(Some("node")), vec!["node".to_string()]);
    assert_eq!(candidates(None), vec!["node".to_string()]);
}

#[test]
fn an_absolute_command_that_is_not_there_does_not_resolve() {
    assert!(locate("/nonexistent/path/to/node", None).is_none());
}

#[test]
fn a_bare_command_with_no_search_path_does_not_resolve() {
    assert!(locate("node", None).is_none());
}

#[cfg(unix)]
#[test]
fn a_bare_command_resolves_through_the_search_path() {
    let path = std::env::var_os("PATH").expect("a host has a PATH");
    assert!(
        locate("sh", Some(&path)).is_some(),
        "PATH lookup found nothing at all"
    );
}

#[cfg(unix)]
#[tokio::test]
async fn a_binary_that_does_not_understand_the_flag_is_not_a_toolchain() {
    // `false --version` exits non-zero, which must read as "not usable" rather
    // than as an empty version string.
    if !Path::new("/bin/false").exists() {
        return;
    }
    assert!(probe_version(Path::new("/bin/false")).await.is_none());
}

#[tokio::test]
